    bool held22 = temporalVisibilityFiniteDepth(stored22) && abs(stored22 - expectedDepth) <= previousTolerance;
    bool held32 = temporalVisibilityFiniteDepth(stored32) && abs(stored32 - expectedDepth) <= previousTolerance;
    bool held03 = temporalVisibilityFiniteDepth(stored03) && abs(stored03 - expectedDepth) <= previousTolerance;
